#[test]
fn generated_target_table_is_unique_and_lookup_is_complete() {
    let mut ids = BTreeSet::new();
    let mut markers = BTreeSet::new();
    let mut abi_ids = BTreeSet::new();
    for group in GENERATED_INTRINSIC_TARGET_GROUPS {
        let mut previous_abi_id = None;
        for target in *group {
            if let Some(previous) = previous_abi_id {
                assert!(
                    previous < target.abi_id,
                    "generated ABI IDs are not strictly increasing: {previous} then {}",
                    target.abi_id
                );
            }
            previous_abi_id = Some(target.abi_id);
            assert!(
                abi_ids.insert(target.abi_id),
                "duplicate generated ABI ID {}",
                target.abi_id
            );
            assert!(
                ids.insert(target.id),
                "duplicate generated intrinsic ID {}",
                target.id
            );
            assert!(
                markers.insert(target.marker),
                "duplicate generated marker {}",
                target.marker
            );
            assert_eq!(
                generated_intrinsic_target_by_marker(target.marker),
                Some(target)
            );
            assert!(
                generated_intrinsic_targets_by_op_name(target.dialect_op)
                    .any(|candidate| candidate == target)
            );
        }
    }
    assert!(generated_intrinsic_target_by_marker("v1:i9999").is_none());
}
